// RAG básico: retrieve -> augment -> generate
async function ragQuery(query, vectorStore, llm) {
  // 1. Retrieve: embeddings similarity search
  const docs = await vectorStore.similaritySearch(query, k=5);

  // 2. Augment: context + query
  const context = docs.map(d => d.content).join('\n---\n');
  const prompt = `Context: ${context}\n\nQuestion: ${query}\nAnswer:`;

  // 3. Generate
  return await llm.generate(prompt, { temperature: 0.1 });
}

// Harness básico: Plan -> Act -> Observe -> Reflect
class AgentHarness {
  constructor(llm, tools, memory) {
    this.llm = llm;
    this.tools = new Map(tools.map(t => [t.name, t]));
    this.memory = memory;
  }

  async run(task) {
    const plan = await this.plan(task);
    for (const step of plan.steps) {
      const result = await this.executeStep(step);
      await this.observe(step, result);
      if (this.shouldReflect()) await this.reflect();
    }
    return this.synthesize();
  }

  async executeStep(step) {
    const tool = this.tools.get(step.tool);
    const result = await tool.execute(step.args, { timeout: 30000 });
    return this.validate(result, step.expectedSchema);
  }
}

