// Orquestador multiagente
class Supervisor {
  constructor(agents) {
    this.agents = new Map(agents.map(a => [a.role, a]));
    this.messageBus = new MessageBus();
  }

  async delegate(task) {
    const plan = await this.planner.decompose(task);

    // Paralelismo: tareas independientes en paralelo
    const independent = plan.steps.filter(s => !s.dependsOn?.length);
    const results = await Promise.all(
      independent.map(step => this.agents.get(step.agent).execute(step))
    );

    // Secuencial: tareas con dependencias
    for (const step of plan.steps.filter(s => s.dependsOn?.length)) {
      await this.waitForDependencies(step.dependsOn);
      await this.agents.get(step.agent).execute(step);
    }

    return this.aggregator.synthesize(results);
  }
}

